// Hot batch 271: sixty-one-instruction functions no route reaches, written by hand from `tools.disasm` and verified
// by synthetic cases (a 64-bit cross-multiplied comparison, cursor moves with wrap-around, a recursive matrix chain,
// pointer rebasing after a move, a tag search over records, list scans and handle-guarded calls through temporaries).
// No names: none has evidence.
#include "decomp_registry.hpp"
#include "gt/game/hot_common.hpp"
#include "guest_call.hpp"

